using System.Security.Claims;using backend.DTOs;using backend.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace backend.Controllers;
[Authorize,ApiController,Route("api/thematic-map")] public sealed class ThematicMapController(IThematicMapService service,IUserPermissionService permissions,ILogger<ThematicMapController> logger):ControllerBase {
 [HttpPost("nearest-stop-distance")]public Task<IActionResult> Distance(ThematicExtentRequest r,CancellationToken ct)=>Run(async()=>await service.GetNearestStopDistanceAsync(r,false,ct));[HttpPost("walking-time")]public Task<IActionResult> Walking(ThematicExtentRequest r,CancellationToken ct)=>Run(async()=>await service.GetNearestStopDistanceAsync(r,true,ct));[HttpPost("route-density")]public Task<IActionResult> Density(ThematicExtentRequest r,CancellationToken ct)=>Run(async()=>await service.GetRouteDensityAsync(r,ct));
 private async Task<IActionResult> Run(Func<Task<object>> action){var id=int.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier),out var x)?x:0;if(id==0)return Unauthorized();if(!await permissions.HasPermissionAsync(id,"ThematicMap.View"))return Forbid();try{return Ok(await action());}catch(ThematicMapValidationException ex){return BadRequest(new{message=ex.Message});}catch(OperationCanceledException){return new StatusCodeResult(499);}catch(Exception ex){logger.LogError(ex,"Tematik harita analizi başarısız.");return StatusCode(500,new{message="Tematik harita analizi sırasında hata oluştu."});}}
}
